import random

def solve_sgp_greedy(n_golfers, n_groups, group_size, n_weeks, max_attempts=1000):
    for attempt in range(max_attempts):
        schedule = [[-1 for _ in range(n_golfers)] for _ in range(n_weeks)]
        played_together = [[False for _ in range(n_golfers)] for _ in range(n_golfers)]

        possible = True
        for w in range(n_weeks):
            # Try to assign golfers to groups
            # To make it more likely to succeed, we can use a random order
            golfers = list(range(n_golfers))
            random.shuffle(golfers)

            # Groups for this week
            groups = [[] for _ in range(n_groups)]

            for p in golfers:
                # Try to assign p to a group
                # A group is valid if it has space and no one in it has played with p
                valid_groups = []
                for g in range(n_groups):
                    if len(groups[g]) < group_size:
                        # Check if any golfer in groups[g] has played with p
                        can_join = True
                        for other in groups[g]:
                            if played_together[p][other]:
                                can_join = False
                                break
                        if can_join:
                            valid_groups.append(g)

                if not valid_groups:
                    possible = False
                    break

                # Choose a random valid group
                g = random.choice(valid_groups)
                groups[g].append(p)
                schedule[w][p] = g

            if not possible:
                break

            # Update played_together
            for g in range(n_groups):
                for i in range(len(groups[g])):
                    for j in range(i + 1, len(groups[g])):
                        p1 = groups[g][i]
                        p2 = groups[g][j]
                        played_together[p1][p2] = True
                        played_together[p2][p1] = True

        if possible:
            return [item for sublist in schedule for item in sublist]
    return None

