from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

def solve_sgp_pysat_fixed(n_golfers, n_groups, group_size, n_weeks):
    def get_var(w, p, g):
        return w * (n_golfers * n_groups) + p * n_groups + g + 1

    solver = Glucose3()

    # 1. Each golfer is in exactly one group per week
    for w in range(n_weeks):
        for p in range(n_golfers):
            solver.add_clause([get_var(w, p, g) for g in range(n_groups)])
            for g1 in range(n_groups):
                for g2 in range(g1 + 1, n_groups):
                    solver.add_clause([-get_var(w, p, g1), -get_var(w, p, g2)])

    # 2. Each group has exactly group_size golfers
    # Use CardEnc.equals with a valid encoding.
    # The error was UnsupportedBound(0, 4). Maybe it needs a higher top_id?
    # Let's use a different encoding or just add clauses manually.
    # Actually, let's use CardEnc.equals with EncType.totalizer.

    top_id = n_weeks * n_golfers * n_groups
    for w in range(n_weeks):
        for g in range(n_groups):
            vars = [get_var(w, p, g) for p in range(n_golfers)]
            # Use a different encoding
            clauses = CardEnc.equals(vars, bound=group_size, encoding=EncType.totalizer, top_id=top_id)
            solver.append_formula(clauses.clauses)
            top_id = clauses.top_id

    # 3. No pair of golfers in the same group more than once
    for p1 in range(n_golfers):
        for p2 in range(p1 + 1, n_golfers):
            for w1 in range(n_weeks):
                for w2 in range(w1 + 1, n_weeks):
                    for g in range(n_groups):
                        solver.add_clause([-get_var(w1, p1, g), -get_var(w1, p2, g), -get_var(w2, p1, g), -get_var(w2, p2, g)])

    if solver.solve():
        model = solver.get_model()
        schedule = [[-1 for _ in range(n_golfers)] for _ in range(n_weeks)]
        for w in range(n_weeks):
            for p in range(n_golfers):
                for g in range(n_groups):
                    if model[get_var(w, p, g) - 1] > 0:
                        schedule[w][p] = g
        return [item for sublist in schedule for item in sublist]
    else:
        return None

result = solve_sgp_pysat_fixed(32, 8, 4, 7)
print(result)
